# -*- coding: utf-8 -*-
"""España / Biología y Geología: 1.º de ESO"""
from es_sci import H, nq, num

D = "¿Qué corresponde a esta descripción: {v}?"


def f_escala(R):
    k = R.choice(["al", "ua", "luz"])
    if k == "al":
        d = R.choice([4.2, 8.6, 25, 2.5, 11, 16, 39])
        return nq("Una estrella está a %s años luz. ¿Cuántos años tarda su luz en llegar a la Tierra?" % num(d), d, [d * 365, d / 2, d * 12], "años",
                  "Un año luz es la distancia que recorre la luz en un año: tarda %s años." % num(d))
    if k == "ua":
        p, d = R.choice([("Marte", 1.5), ("Júpiter", 5.2), ("Saturno", 9.5), ("Venus", 0.72), ("Neptuno", 30), ("Urano", 19)])
        return nq("%s está a unas %s UA del Sol. Si 1 UA ≈ 150 millones de km, ¿a cuántos millones de km está?" % (p, num(d)), d * 150, [d * 15, d + 150, 150 / d], "millones de km",
                  "%s × 150 = %s millones de km." % (num(d), num(d * 150)))
    if k == "luz":
        d = R.choice([150, 228, 778, 58, 108, 300])
        t = d * 1e6 / 300000 / 60
        return nq("La luz viaja a unos 300 000 km/s. ¿Cuántos minutos tarda en recorrer %s millones de km?" % num(d), t, [t * 60, t / 60, d / 300], "min",
                  "%s 000 000 km : 300 000 km/s = %s s ≈ %s min." % (num(d), num(d * 1e6 / 300000), num(t)))



