          ["El nombre científico tiene género y especie.", "Linneo creó la nomenclatura binomial.", "La especie es la categoría más concreta.", "Las bacterias son moneras.", "Los virus no son células.",
           "El burro y el caballo son especies distintas.", "Los hongos tienen pared de quitina."],
          [("El reino es la categoría más concreta.", "Es la más amplia."), ("Los virus son un reino.", "No se incluyen en los reinos."), ("Las setas son plantas.", "Son hongos."),
           ("El género se escribe con minúscula.", "Se escribe con mayúscula."), ("Las algas son animales.", "Son protoctistas.")],
