          [("Todas las plantas tienen flores.", "Musgos y helechos no."), ("El pino es una angiosperma.", "Es una gimnosperma."), ("Las plantas solo respiran de noche.", "Respiran siempre."),
           ("El óvulo se convierte en fruto.", "Se convierte en semilla."), ("Los musgos tienen semillas.", "Tienen esporas.")],
